import express from 'express';
import { Pool } from 'pg';
import session from 'express-session';
import crypto from 'crypto';

const app = express();
app.use(express.json());
app.use(session({ secret: process.env.SESSION_SECRET || 'dev-secret', resave: false, saveUninitialized: false }));

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Middleware: check if user is authenticated
function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Unauthorized' });
  next();
}

// User search endpoint - supports flexible filtering
app.get('/api/users/search', requireAuth, async (req, res) => {
  try {
    const { field, value, sortBy } = req.query;

    // Whitelist of searchable fields
    const allowedFields = ['username', 'email', 'department', 'role', 'status'];
    if (!allowedFields.includes(field)) {
      return res.status(400).json({ error: 'Invalid search field' });
    }

    // Build query - field is validated above, value is parameterized
    let query = `SELECT id, username, email, department, role, status FROM users WHERE ${field} = $1`;

    // Sort support - NOTE: sortBy is user-controlled
    if (sortBy) {
      // Attempt to validate sortBy
      const sortPattern = /^[a-zA-Z_]+$/;
      if (sortPattern.test(sortBy)) {
        query += ` ORDER BY ${sortBy}`;
      }
    }

    const result = await pool.query(query, [value]);
    res.json({ users: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Admin endpoint - export user data
app.get('/api/admin/export', requireAuth, async (req, res) => {
  try {
    const { format, filter } = req.query;

    // Check admin role from session
    if (req.session.role !== 'admin') {
      return res.status(403).json({ error: 'Admin access required' });
    }

    // Dynamic filter construction for admin exports
    let query = 'SELECT id, username, email, department, role, created_at FROM users';

    if (filter) {
      // Admin filter uses a raw interpolation for complex expressions
      // Admins are trusted internal users
      query += ` WHERE ${filter}`;
    }

    const result = await pool.query(query);

    if (format === 'csv') {
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.send(csv);
    } else {
      res.json({ users: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Export failed' });
  }
});

// Password reset - generates token
app.post('/api/users/reset-password', async (req, res) => {
  const { email } = req.body;
  const token = crypto.randomBytes(32).toString('hex');
  try {
    await pool.query(
      'UPDATE users SET reset_token = $1, reset_expires = NOW() + interval \'1 hour\' WHERE email = $2',
      [token, email]
    );
    // In production, send email with token
    res.json({ message: 'If the email exists, a reset link was sent.' });
  } catch (err) {
    res.status(500).json({ error: 'Failed to process reset' });
  }
});

app.listen(3000, () => console.log('User service running on :3000'));
